describe('Modal Independent Scrolling', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal"]').should('be.visible');
  });

  it('should scroll modal content independently when content overflows', () => {
    // Verify modal is visible and scrollable
    cy.get('[data-testid="modal-content"]').should('be.visible');

    // Get initial scroll position
    cy.get('[data-testid="modal-content"]').then(($content) => {
      const initialScrollTop = $content[0].scrollTop;
      expect(initialScrollTop).to.equal(0);
    });

    // Scroll modal content
    cy.get('[data-testid="modal-content"]').scrollTo(0, 500);

    // Verify modal content scrolled independently
    cy.get('[data-testid="modal-content"]').then(($content) => {
      expect($content[0].scrollTop).to.be.greaterThan(0);
    });

    // Verify body/page did not scroll
    cy.window().then((win) => {
      expect(win.scrollY).to.equal(0);
    });

    // Verify modal remains visible after scrolling
    cy.get('[data-testid="modal"]').should('be.visible');
  });

  it('should handle edge case where modal content is exactly at scroll boundary', () => {
    // Get modal content element
    cy.get('[data-testid="modal-content"]').then(($content) => {
      const scrollHeight = $content[0].scrollHeight;
      const clientHeight = $content[0].clientHeight;
      const maxScroll = scrollHeight - clientHeight;

      // Scroll to maximum position
      cy.get('[data-testid="modal-content"]').scrollTo(0, maxScroll);

      // Verify at bottom boundary
      cy.get('[data-testid="modal-content"]').then(($scrolledContent) => {
        expect($scrolledContent[0].scrollTop).to.equal(maxScroll);
      });

      // Attempt to scroll beyond boundary
      cy.get('[data-testid="modal-content"]').scrollTo(0, maxScroll + 100);

      // Verify scroll position capped at max
      cy.get('[data-testid="modal-content"]').then(($boundedContent) => {
        expect($boundedContent[0].scrollTop).to.equal(maxScroll);
      });
    });

    // Verify page still not scrolled
    cy.window().then((win) => {
      expect(win.scrollY).to.equal(0);
    });
  });

  it('should maintain modal scroll position when interacting with elements', () => {
    // Scroll modal to middle position
    cy.get('[data-testid="modal-content"]').scrollTo(0, 300);

    // Record scroll position
    let scrollPosition = 0;
    cy.get('[data-testid="modal-content"]').then(($content) => {
      scrollPosition = $content[0].scrollTop;
    });

    // Click button inside modal
    cy.get('[data-testid="modal-action-btn"]').click();

    // Verify scroll position maintained
    cy.get('[data-testid="modal-content"]').then(($content) => {
      expect($content[0].scrollTop).to.equal(scrollPosition);
    });
  });

  it('should prevent body scroll when modal is open with overflowing content', () => {
    // Get initial body scroll
    cy.window().then((win) => {
      const initialBodyScroll = win.scrollY;
      expect(initialBodyScroll).to.equal(0);
    });

    // Try to scroll body while modal is open
    cy.get('body').scrollTo(0, 500, { duration: 100 });

    // Verify body did not scroll
    cy.window().then((win) => {
      expect(win.scrollY).to.equal(0);
    });

    // Verify modal content is still scrollable
    cy.get('[data-testid="modal-content"]').scrollTo(0, 200);
    cy.get('[data-testid="modal-content"]').then(($content) => {
      expect($content[0].scrollTop).to.be.greaterThan(0);
    });
  });

  it('should restore page scroll after modal closes', () => {
    // Set initial page scroll position
    cy.window().then((win) => {
      win.scrollTo(0, 100);
    });

    // Verify page is scrolled
    cy.window().then((win) => {
      expect(win.scrollY).to.equal(100);
    });

    // Open modal
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal"]').should('be.visible');

    // Scroll modal content
    cy.get('[data-testid="modal-content"]').scrollTo(0, 300);

    // Close modal
    cy.get('[data-testid="close-modal-btn"]').click();
    cy.get('[data-testid="modal"]').should('not.be.visible');

    // Verify page scroll position restored
    cy.window().then((win) => {
      expect(win.scrollY).to.equal(100);
    });
  });
});
